//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/listing_iss_common.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vSecugrpID, scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;
scwin.visuShrsLabelNm = "주식";
scwin.vScrenID = "ULDSTF92001.xml";
scwin.strCbd_NPARVALSTK_YN = "N^아니오,Y^예";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00443 - 통화ISO코드
    */
    var arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CURR_ISO_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.resizeToWin = function() {
    //frame.Width = 280;
    //frame.Height = 420;
    $c.stf.MoveCenterOfParent();
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == 'I') {
        img_ISU_CD.src = "../img/btn_search.gif";
        img_ISU_CD.setDisabled(false);
    } else if (initTyp == 'X') {
        img_ISU_CD.src = "../img/btn_search_d.gif";
        img_ISU_CD.setDisabled(true);
    }
};
scwin.fn_setSumblComponent = function() {
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
        txb_ISU_ENG_SYMBL.setReadOnly(false);
        txb_ISU_ENG_SYMBL.style.backgroundColor = '#ffffff';
        $c.stf.showObj(img_ISU_ENG_SYMBL, true);
    } else {
        txb_ISU_ENG_SYMBL.setReadOnly(true);
        txb_ISU_ENG_SYMBL.style.backgroundColor = '#b9d4f7';
        $c.stf.showObj(img_ISU_ENG_SYMBL, false);
    }
};
scwin.fn_setInitLabel = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        scwin.visuShrsLabelNm = "DR";
        $c.stf.setObjectValue(lb_PARVAL, 'DR당액면가/주당자본금');
        $c.stf.setObjectValue(lb_BF_ACC_ISU_SHRS, '변경전 상장DR수');
        $c.stf.setObjectValue(lb_ISU_SHRS, '증감상장DR수');
        $c.stf.setObjectValue(lb_ACC_ISU_SHRS, '변경후 상장DR수');

        //showObj(panel_PARVAL, false);
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
            $c.stf.showObj(panel_ISU_CAP, false);
        }
    } else {
        scwin.visuShrsLabelNm = "주식";
        $c.stf.showObj(panel_PARVAL, true);
        $c.stf.showObj(panel_ISU_CAP, true);
    }
    if (scwin.vSecugrpID == SECUGRP_ID_DR || scwin.vSecugrpID == SECUGRP_ID_FS) {
        edt_PARVAL.MaxDecimalPlace = 3;
        edt_ISU_CAP.MaxDecimalPlace = 3;
    } else {
        edt_PARVAL.MaxDecimalPlace = 0;
        edt_ISU_CAP.MaxDecimalPlace = 0;
    }
};
scwin.fn_SetComboCode = function() {
    cmb_NPARVALSTK_YN.CBData = scwin.strCbd_NPARVALSTK_YN;
    cmb_NPARVALSTK_YN.setSelectedIndex(0);
    $c.stf.showObj(edt_PARVAL, true);
    $c.stf.showObj(edt_PER1STK_CAP, false);
    $c.stf.setObjectValue(edt_PER1STK_CAP, "0");
    var url = "/CodeAction.do?method=listStkIsuRsnCd&inputMessageId=STK_ISU_RSN_CD_OUT";
    url += "&LD_MKT_TP_CD=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    //발행사유코드
    dts_STK_ISU_RSN_CD.DataID = encodeURI(url);
    dts_STK_ISU_RSN_CD.Reset();
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vSecugrpID;
    arrPar[1] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    //var dbClickYn =  arrPar[0].DBCLICKYN;
    if (arrPar[0].ISU_CD != "") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        txb_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        txb_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        txb_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        txb_ISU_ENG_SYMBL.setValue(arrPar[0].ISU_ENG_SYMBL);
        $c.stf.setObjectValue(cmb_CURR_ISO_CD, arrPar[0].CURR_ISO_CD);
        if (scwin.vSecugrpID == SECUGRP_ID_DR) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, 'KDR'); //주식의종류코드를 셋팅 

        } else if (scwin.vSecugrpID == SECUGRP_ID_FS) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, '000'); //주식의종류코드를 셋팅 

        } else {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, $c.stf.getObjectValue(txb_ISU_CD).substring(8, 11)); //주식의종류코드를 셋팅 

        }
        scwin.fn_setPREFSTKEvent();
        scwin.fn_nprefstk_read_sync(txb_ISU_CD.getValue());
        scwin.fn_bf_read_sync();
    }
};



/**
 * 변경전 주식수, 자본금 가져오기
 */
scwin.fn_bf_read_sync = function() {
    $c.lic.fn_bf_read_sync1(dts_BfData, txb_ISU_CD, edt_LIST_DD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP);
};
scwin.fn_setPREFSTKEvent = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_ST) {
        if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == '000') {
            scwin.fn_setPREFSTKItem(false);
        } else {
            scwin.fn_setPREFSTKItem(true);
        }
    } else {
        scwin.fn_setPREFSTKItem(false);
    }
};
scwin.fn_setPanelPREFSTK = function(isTrue) {
    $c.stf.showObj(panel_PREFSTK, isTrue);
};
scwin.fn_setPREFSTKItem = function(isTrue) {
    $c.stf.showObj(chk_PREFSTK_TP_CD, isTrue);
    $c.stf.showObj(label_PREFSTK_TP_CD, isTrue);
};
scwin.fn_nprefstk_read_sync = function(isucd) {
    var url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_NEWPREFSTK_STK_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ISU_CD=" + isucd;
    dts_NEWPREFSTK.DataID = encodeURI(url);
    dts_NEWPREFSTK.Reset();
    if (dts_NEWPREFSTK.getTotalRow() > 0) {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", dts_NEWPREFSTK.getCellData(1, "ISU_DD"));
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", dts_NEWPREFSTK.getCellData(1, "PREFSTK_DIV_RT"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_MM"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS"));
        dts_Isu.setCellData(1, "PREFSTK_END_DD", dts_NEWPREFSTK.getCellData(1, "PREFSTK_END_DD"));
        dts_Isu.setCellData(1, "INDEFINPD_YN", dts_NEWPREFSTK.getCellData(1, "INDEFINPD_YN"));
        dts_Isu.setCellData(1, "PARTCTP_YN", dts_NEWPREFSTK.getCellData(1, "PARTCTP_YN"));
        dts_Isu.setCellData(1, "ACCTP_YN", dts_NEWPREFSTK.getCellData(1, "ACCTP_YN"));
        dts_Isu.setCellData(1, "NDIVTM_VOTERGHT_YN", dts_NEWPREFSTK.getCellData(1, "NDIVTM_VOTERGHT_YN"));
        dts_Isu.setCellData(1, "NEWPREFSTK_REMK", dts_NEWPREFSTK.getCellData(1, "NEWPREFSTK_REMK"));
        chk_PREFSTK_TP_CD.setValue(1);
        scwin.fn_setPREFSTKItem(true);
        scwin.fn_setPanelPREFSTK(true);
        //alert(dts_NEWPREFSTK.Text);

    } else {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", '');
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", '');
        dts_Isu.setCellData(1, "PREFSTK_END_DD", '');
        dts_Isu.setCellData(1, "INDEFINPD_YN", '');
        dts_Isu.setCellData(1, "PARTCTP_YN", '');
        dts_Isu.setCellData(1, "ACCTP_YN", '');
        dts_Isu.setCellData(1, "NDIVTM_VOTERGHT_YN", '');
        dts_Isu.setCellData(1, "NEWPREFSTK_REMK", '');
        chk_PREFSTK_TP_CD.setValue(0);
        scwin.fn_setPanelPREFSTK(false);
        scwin.fn_setPREFSTKEvent();
        //dts_NEWPREFSTK.DeleteRow(1);

    }
};
scwin.fn_setCheckboxData = function(obj, val) {
    if (val == 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};
scwin.fn_getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};
scwin.fn_read_sync = function() {
    var url = "/Newlisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_ST_ISU_DTL;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    if (dts_Isu.getCellData(1, "PREFSTK_TP_CD") == '2') {
        chk_PREFSTK_TP_CD.setValue(1);
        scwin.fn_setPREFSTKItem(true);
        scwin.fn_setPanelPREFSTK(true);
    } else {
        scwin.fn_setPREFSTKEvent();
    }
    scwin.fn_setCheckboxData(chk_INDEFINPD_YN, dts_Isu.getCellData(1, "INDEFINPD_YN"));
    scwin.fn_setCheckboxData(chk_PARTCTP_YN, dts_Isu.getCellData(1, "PARTCTP_YN"));
    scwin.fn_setCheckboxData(chk_ACCTP_YN, dts_Isu.getCellData(1, "ACCTP_YN"));
    scwin.fn_setCheckboxData(chk_NDIVTM_VOTERGHT_YN, dts_Isu.getCellData(1, "NDIVTM_VOTERGHT_YN"));
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        $c.stf.showObj(edt_PARVAL, false);
        $c.stf.showObj(edt_PER1STK_CAP, true);
        $c.stf.setObjectValue(edt_PARVAL, "0");
    } else {
        $c.stf.showObj(edt_PARVAL, true);
        $c.stf.showObj(edt_PER1STK_CAP, false);
        $c.stf.setObjectValue(edt_PER1STK_CAP, "0");
    }
};
scwin.fn_DisclsYn = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=STKCERT_NEWLIST_DISCLSYN_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.stkcert.newlist.disclsYn.confrm.condition";
    url += "&{P}param01=" + scwin.vBzProcsNo;
    dts_DisclsYn.DataID = encodeURI(url);
    dts_DisclsYn.Reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[법인코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        //유가일경우에는 푼다.

        //if ( fn_checkDoubleInput(getObjectValue(txb_ISU_CD)) )  return false;

    }

    //if (getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_1) {
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다."); //txb_ISU_SRT_CD.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_NM) == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 60, "한글종목명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 30, "한글종목약명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) return false;
    if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV) == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 30, "영문종목약명")) return false;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        if ($c.stf.getObjectValue(txb_ISU_ENG_SYMBL) == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISU_ENG_SYMBL))) {
            if (!$c.lc.fn_chkCorpSymblDoubleInput($c.stf.getObjectValue(txb_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
    }
    //}

    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_RND) == "") {
        $c.win.alert("[발행회차]를 입력하세요.");
        edt_ISU_RND.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == "") {
        $c.win.alert("[주식의종류]를 선택하세요.");
        cmb_STKCERT_KIND_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "") {
        $c.win.alert("[주식발행사유]를 선택하세요.");
        cmb_STK_ISU_RSN_CD.focus();
        return false;
    }

    ///*
    if (scwin.vSecugrpID != SECUGRP_ID_MF && scwin.vSecugrpID != SECUGRP_ID_IF && scwin.vSecugrpID != SECUGRP_ID_DR) {
        if ($c.stf.getObjectValue(edt_PARVAL) == "") {
            $c.win.alert("[액면가]을 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }
        if (!scwin.fn_checkNumber(edt_PARVAL, '액면가')) return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_PRC) == "") {
        $c.win.alert("[발행가]을 입력하세요.");
        edt_ISU_PRC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_SHRS) == "") {
        $c.win.alert("[증감" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
        edt_ISU_SHRS.focus();
        return false;
    }
    if (scwin.vSecugrpID != SECUGRP_ID_DR) {
        /*
        		if (getObjectValue(edt_ACC_ISU_SHRS) == "") {
        			alert("[상장주식수]을 입력하세요.");edt_ACC_ISU_SHRS.focus();return false;
        		}
        		if (! fn_checkNumber(edt_ACC_ISU_SHRS, '상장주식수')) return false;
        */
        if ($c.stf.getObjectValue(edt_ISU_CAP) == "") {
            $c.win.alert("[증감 상장자본금]을 입력하세요.");
            edt_ISU_CAP.focus();
            return false;
        }
        //if (! fn_checkNumber(edt_ISU_CAP, '증감 상장자본금')) return false;


        if ($c.stf.getObjectValue(edt_ACC_ISU_SHRS) == "") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_SHRS) == "0") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]값이 '0' 입니다. \n[증감 상장" + scwin.visuShrsLabelNm + "수]가 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_CAP) == "") {
            $c.win.alert("[변경후 상장자본금]을 입력하세요.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ACC_ISU_CAP) == "0") {
            $c.win.alert("[변경후 상장자본금]값이 '0' 입니다. '\n[증감 상장자본금]이 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(edt_DIV_RECK_DD1) == "") {
        $c.win.alert("[배당기산일1]을 입력하세요.");
        edt_DIV_RECK_DD1.focus();
        return false;
    }
    //*/
    if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == "000" || $c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == "KDR") {
        if (chk_PREFSTK_TP_CD.checked) {
            $c.win.alert("[신형우선주여부]는 우선주일 경우에만 선택하십시요.");
            chk_PREFSTK_TP_CD.focus();
            return false;
        }
    }
    if (chk_PREFSTK_TP_CD.checked) {
        if ($c.stf.getObjectValue(edt_PREFSTK_DIV_RT) == "") {
            $c.win.alert("[우선주배당률]을 입력하세요.");
            edt_PREFSTK_DIV_RT.focus();
            return false;
        }
    }

    //보통주일경우 한글회사약명, 종목약명이 같지 않으면 메시지 출력 (YSH, 2012/02/02)
    var stkKindCd = dts_Isu.getCellData(1, "STKCERT_KIND_CD");
    if (stkKindCd != undefined) {
        if ("000" == stkKindCd) {
            //보통주
            var parentWin = $c.frame.path("../");
            if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) != $c.stf.getObjectValue(parentWin.txb_COM_ABBRV)) {
                $c.win.alert("보통주일경우 한글회사약명 과 종목약명이 동일해야 합니다. 확인하시기 바랍니다.");
                txb_ISU_KOR_ABBRV.focus();
                return false;
            }
        }
    }
    /* 2012.12.10 이세민(050899,상장제도팀) 요청으로 검증로직 주석처리
		if( getObjectValue(cmb_NPARVALSTK_YN) ==  "Y" ){
		    var PER1STK_CAP =  eval(parseFloat(getObjectValue(edt_PER1STK_CAP)));
			var ISU_PRC =  eval(parseFloat(getObjectValue(edt_ISU_PRC)));
            if(  PER1STK_CAP >  ISU_PRC ){
			     alert('주당자본계상금은  발행가 이하로 입력해 주십시오.');
				  edt_PER1STK_CAP.focus();return false;
			}
			if( PER1STK_CAP < (ISU_PRC*0.5) ){
			      alert('주당자본계상금은 발행가의 50% 이상으로 입력해 주십시오');
				  edt_PER1STK_CAP.focus();return false;
			}
		}
		*/
    return true;
};
