scwin.calcuAccIsuShrs = function() {
    try {
        var vsum = eval(parseInt($c.stf.getObjectValue(edt_BF_ACC_ISU_SHRS))) + eval(parseInt($c.stf.getObjectValue(edt_ISU_SHRS)));
        //alert( "[vsum]"+vsum);
        $c.stf.setObjectValue(edt_ACC_ISU_SHRS, vsum);
    } catch (err) {
        $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};
scwin.calcusuCap = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        $c.stf.setObjectValue(edt_ISU_CAP, '');
    } else {
        try {
            var vRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
            var vsum = 0;
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //약면변합
                vRsnCd == '171') {
                //액면분할
                vsum = 0; //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //약면변합
                vRsnCd == '641') {
                //액면분할
                vsum = 0; //코스닥

            } else {
                if (scwin.vSecugrpID == SECUGRP_ID_MF || scwin.vSecugrpID == SECUGRP_ID_IF) {
                    vsum = eval(parseFloat($c.stf.getObjectValue(edt_ISU_PRC))) * eval(parseFloat($c.stf.getObjectValue(edt_ISU_SHRS)));
                } else {
                    vsum = eval(parseFloat($c.stf.getObjectValue(edt_PARVAL))) * eval(parseFloat($c.stf.getObjectValue(edt_ISU_SHRS)));
                }
            }
            //alert( "[증감자본금 vsum]"+vsum);
            $c.stf.setObjectValue(edt_ISU_CAP, vsum);
        } catch (err) {
            $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};
scwin.calcuAccIsuCap = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        $c.stf.setObjectValue(edt_ACC_ISU_CAP, '');
    } else {
        try {
            var vRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
            var vsum = '';
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //약면변합
                vRsnCd == '171') {
                //액면분할
                vsum = $c.stf.getObjectValue(edt_BF_ACC_ISU_CAP); //유가
                $c.stf.setObjectValue(edt_ISU_CAP, 0); //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //약면변합
                vRsnCd == '641') {
                //액면분할
                vsum = $c.stf.getObjectValue(edt_BF_ACC_ISU_CAP); //코스닥
                $c.stf.setObjectValue(edt_ISU_CAP, 0); //코스닥

            } else {
                scwin.calcusuCap();
                vsum = eval(parseFloat($c.stf.getObjectValue(edt_BF_ACC_ISU_CAP))) + eval(parseFloat($c.stf.getObjectValue(edt_ISU_CAP)));
            }
            $c.stf.setObjectValue(edt_ACC_ISU_CAP, vsum);
        } catch (err) {
            $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};
