scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_Isu.setFocusedCell(rowPos, 0);
    }
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
        scwin.fn_DisclsYn();

        // 공시여부가 Y인 경우 삭제를 못하도록 막음..(2015.11.26)
        if (dts_DisclsYn.getTotalRow() > 0) {
